function moveZeros(list) {
  var nonZero = list.filter(function (x) {
    return x !== 0;
  });
  var zeros = list.length - nonZero.length;
  for (var i = 0; i < zeros; i++) {
    nonZero.push(0);
  }
  return nonZero;
}

console.log(moveZeros([0, 1, 0, 3, 12]));
